import { fmt, n, q, num, L, U } from "./ee-shape.mjs";

const sqrt3 = Math.sqrt(3);
const vArm = 220;
const iArm = 10;
const ra = 1;
const eb = vArm - iArm * ra;
const pConv = eb * iArm;
const nRpm = 1500;
const omega = (nRpm * 2 * Math.PI) / 60;
const torque = pConv / omega;
const ebGen = vArm + iArm * ra;
const pElecGen = vArm * iArm;
const pMechGen = ebGen * iArm;
const pCu = iArm * iArm * ra;
const pFric = 50;
const pShaft = pConv - pFric;
const tShaft = pShaft / omega;
const nWeak = nRpm * 2;
const kPhi = eb / omega;

const pElec = 3000;
const sApp = pElec / 0.75;
const iInd = sApp / (sqrt3 * 400);
const rEq = 30;
const xEq = Math.sqrt(40 * 40 - 30 * 30);
const slip = 0.04;
const ns = (120 * 50) / 4;
const nr = ns * (1 - slip);
const pDev = 2500;
const pAg = pDev / (1 - slip);
const pRcu = slip * pAg;
const pLockAg = 8000;

const fe4 = (1500 * 4) / 120;
const n6 = (120 * 50) / 6;
const pSync = 3000;
const tSync = pSync / omega;
const iUnity = pSync / (sqrt3 * 400);
const kt = 0.2;
const iBldc = 5;
const tBldc = kt * iBldc;
const wBldc = (3000 * 2 * Math.PI) / 60;
const eBldc = kt * wBldc;
const feBldc = (3000 * 4) / 120;
const fePairs = (3000 * 2) / 120;

